#include "cloudmoon_session.h"
#include <string.h>
static int hexval(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
static int decode_string(const char*p,const char*end,char*out,size_t cap,size_t*used){size_t n=0;const char*s;if(!p||p>=end||*p!='"'||!out||!cap)return -1;s=p+1;while(s<end&&*s!='"'){unsigned char c=(unsigned char)*s++;if(c=='\\'){int a,b;if(s>=end)return -1;c=(unsigned char)*s++;switch(c){case '"':case '\\':case '/':break;case 'b':c='\b';break;case 'f':c='\f';break;case 'n':c='\n';break;case 'r':c='\r';break;case 't':c='\t';break;case 'u':if(end-s<4)return -1;a=hexval(s[0]);b=hexval(s[1]);if(a<0||b<0||hexval(s[2])<0||hexval(s[3])<0)return -1;c=(unsigned char)((a<<4)|b);s+=4;if(c>=128)c='?';break;default:return -1;}}if(n+1>=cap)return -1;out[n++]=(char)c;}if(s>=end||*s!='"')return -1;out[n]=0;if(used)*used=(size_t)(s+1-p);return (int)n;}
static const char*skip_ws(const char*p,const char*end){while(p<end&&(*p==' '||*p=='\t'||*p=='\r'||*p=='\n'))p++;return p;}
static const char*json_value_end(const char*p,const char*end){int depth=0,ins=0,esc=0;const char*s;for(s=p;s<end;s++){char c=*s;if(ins){if(esc)esc=0;else if(c=='\\')esc=1;else if(c=='"')ins=0;continue;}if(c=='"')ins=1;else if(c=='{'||c=='[')depth++;else if(c=='}'||c==']'){if(depth==0)break;if(--depth==0)return s+1;}else if(c==','&&depth==0)break;}return s;}
int cm_socketio_parse_event(const char*packet,cm_sio_event_t*ev){const char*p,*end,*ns,*ps,*pe;size_t used;char name[64];if(!packet||!ev||packet[0]!='4'||packet[1]!='2')return -1;p=packet+2;end=packet+strlen(packet);p=skip_ws(p,end);if(p>=end||*p++!='[')return -1;p=skip_ws(p,end);ns=p;if(decode_string(p,end,name,sizeof(name),&used)<0)return -1;p+=used;p=skip_ws(p,end);if(p>=end||*p++!=',')return -1;ps=skip_ws(p,end);pe=json_value_end(ps,end);if(pe<=ps)return -1;while(pe>ps&&(pe[-1]==' '||pe[-1]=='\t'||pe[-1]=='\r'||pe[-1]=='\n'))pe--;ev->name=ns+1;ev->name_len=used-2;ev->payload=ps;ev->payload_len=(size_t)(pe-ps);if(!strcmp(name,"hello_server"))ev->type=CM_SIO_EVENT_HELLO_SERVER;else if(!strcmp(name,"action_done2"))ev->type=CM_SIO_EVENT_ACTION_DONE2;else if(!strcmp(name,"msg"))ev->type=CM_SIO_EVENT_MSG;else if(!strcmp(name,"getout"))ev->type=CM_SIO_EVENT_GETOUT;else ev->type=CM_SIO_EVENT_OTHER;return 0;}
int cm_json_get_string(const char*json,size_t len,const char*key,char*out,size_t cap){const char*p,*end;char found[256];if(!json||!key||!out||!cap)return -1;p=skip_ws(json,json+len);end=json+len;if(p>=end||*p++!='{')return -1;while(p<end){size_t used;p=skip_ws(p,end);if(p<end&&*p=='}')break;if(decode_string(p,end,found,sizeof(found),&used)<0)return -1;p+=used;p=skip_ws(p,end);if(p>=end||*p++!=':')return -1;p=skip_ws(p,end);if(!strcmp(found,key)){if(p>=end||*p!='"')return -1;return decode_string(p,end,out,cap,0);}p=json_value_end(p,end);p=skip_ws(p,end);if(p<end&&*p==',')p++;else if(p<end&&*p=='}')break;else return -1;}return -1;}
void cm_session_init(cm_session_t*s){if(!s)return;memset(s,0,sizeof(*s));s->state=CM_SESSION_DISCONNECTED;}
cm_session_action_t cm_session_on_event(cm_session_t*s,const cm_sio_event_t*ev){if(!s||!ev)return CM_SESSION_ACTION_NONE;switch(ev->type){case CM_SIO_EVENT_HELLO_SERVER:if(s->state==CM_SESSION_SOCKET_CONNECTED||s->state==CM_SESSION_DISCONNECTED){s->state=CM_SESSION_CLIENT_REGISTER_SENT;return CM_SESSION_ACTION_SEND_CLIENT_REGISTER;}return CM_SESSION_ACTION_NONE;case CM_SIO_EVENT_ACTION_DONE2:if(cm_json_get_string(ev->payload,ev->payload_len,"roomid",s->room_id,sizeof(s->room_id))<0&&cm_json_get_string(ev->payload,ev->payload_len,"roomId",s->room_id,sizeof(s->room_id))<0){s->state=CM_SESSION_ERROR;return CM_SESSION_ACTION_NONE;}if(cm_json_get_string(ev->payload,ev->payload_len,"clientid",s->client_id,sizeof(s->client_id))<0&&cm_json_get_string(ev->payload,ev->payload_len,"clientId",s->client_id,sizeof(s->client_id))<0)strcpy(s->client_id,"1111111");s->state=CM_SESSION_ROOM_REGISTER_SENT;return CM_SESSION_ACTION_SEND_REGISTER;case CM_SIO_EVENT_MSG:if(s->state==CM_SESSION_ROOM_REGISTER_SENT||s->state==CM_SESSION_CLIENT_REGISTER_SENT||s->state==CM_SESSION_SIGNALING){s->state=CM_SESSION_SIGNALING;return CM_SESSION_ACTION_HANDLE_SIGNAL;}return CM_SESSION_ACTION_NONE;case CM_SIO_EVENT_GETOUT:s->state=CM_SESSION_CLOSED;return CM_SESSION_ACTION_STOP;default:return CM_SESSION_ACTION_NONE;}}
